-- QuickBinds minimap button: a plain Button parented to `Minimap`, sized like its
-- neighbours and shaped by its disc art (Media/icon.tga, generated by tools/make-icon.py
-- — gold rim, silver inner ring, dark plate with the QB legend, the treatment the other
-- minimap buttons share). C_Minimap has no RegisterMinimapButton on this client
-- (tools/check-apis.mjs asserts its absence), so this is the manual LibDBIcon-style build
-- with no external libraries. Why `Minimap` is the home while `MinimapCluster` only lends
-- its rank: v0.1.5 asked for a level and left the stratum inherited, so the button stayed
-- under the bronze ring; v0.1.6 copied the cluster's stratum and finally drew over the
-- ring, but did it by parenting to `MinimapCluster`, which inherits `ResizeLayoutFrame`
-- (Blizzard_Minimap/Mainline/Minimap.xml:3) and resizes itself to fit its children — the
-- reporter's two captures of one 578x434 screen show the minimap's edit-mode frame going
-- from 201 px to 326 px wide. v0.1.7 keeps the raise, moves the home back to `Minimap`
-- (whose children never move those bounds; every other addon button lives there) and reads
-- the level and stratum from a named `raiseSource`; the hover glow comes from the
-- minimap's own highlight texture.
-- Left-drag moves the button (StartMoving consumes the press, so a click only fires when
-- you don't drag), but only around the minimap: where the drag ends is read as an angle
-- and rebuilt as the ring point at that angle, and QuickBindsDB.minimapButton keeps that
-- angle — v0.1.1's free viewport x/y still load, projected onto the ring. `/qbcenter`
-- clears the saved angle and puts the button back at the top of the ring.

local QuickBinds = QuickBinds;

-- The frame's edge length in UI units, measured off the requester's v0.1.5 screenshot:
-- the two neighbouring addon buttons render 27 px wide there, and their UI scale is
-- ~1.1 (the 198-unit `Minimap` frame draws as the 215 px terrain circle in the same
-- image), so a neighbour is 27 px / 1.1 = 24 units. That is 0.75× the 32 v0.1.4 and
-- v0.1.5 shipped, which read as too large on the ring. The art is an inscribed disc, so
-- the same file renders correctly at the smaller frame; only the frame changes.
local SIZE = 24;
local ICON_PATH = "Interface\\AddOns\\QuickBinds\\Media\\icon.tga";
local MOUSE_HILIGHT = "Interface\\Buttons\\UI-Common-MouseHilight";
-- The orbit the button rides, in the coordinate space SetPoint uses (UIParent units).
-- Its radius is the minimap's own: `self:GetWidth() / 2` is how Blizzard measures the
-- minimap circle (MinimapMixin:OnClick, Blizzard_Minimap/Mainline/Minimap.lua:164, on a
-- 198x198 square frame — Minimap.xml:179). The anchor this button used before the ring,
-- `SetPoint("CENTER", Minimap, "TOP", 0, 4)`, sat 4 points above that edge, so the ring
-- keeps that lift and the default position is the spot it has always used.
local DEFAULT_LIFT = 4;
local DEFAULT_ANGLE = math.pi / 2; -- straight up: the top of the ring

local button;
-- The frame the level and the stratum are read from, set by CreateButton to
-- `MinimapCluster or Minimap` and the only source of rank this frame ever takes. It is
-- deliberately not the parent: the parent is `Minimap` (see CreateButton) so the
-- ResizeLayoutFrame cluster keeps its bounds, while the rank still comes from the frame
-- that owns the ring art (see RaiseAboveBorder).
local raiseSource;

-- The one way this frame is ever raised, applied at creation and re-applied whenever the
-- client restamps the cluster's levels (see the OnEvent handler at the bottom of the
-- file). A frame level only ranks frames inside one stratum, so the level and the stratum
-- both come from `raiseSource` — Blizzard's own recipe for putting a frame over that
-- cluster (MinimapClusterMixin:OnLoad, Blizzard_Minimap/Mainline/Minimap.lua:373-374
-- raises the cluster's over-the-border ornament InstanceDifficulty with
-- `local raisedFrameLevel = self:GetFrameLevel() + 10;`
-- `self.InstanceDifficulty:SetFrameLevel(raisedFrameLevel)`).
local function RaiseAboveBorder()
    button:SetFrameStrata(raiseSource:GetFrameStrata());
    button:SetFrameLevel(raiseSource:GetFrameLevel() + 10);
end

-- Minimap centre and orbit radius in UIParent units: GetCenter/GetWidth speak the
-- minimap's scale, so both go through the conversion v0.1.1 saved with and v0.1.5 kept —
-- `Minimap:GetEffectiveScale() / UIParent:GetEffectiveScale()`. v0.1.6 asked the button
-- for its scale instead, which scales the whole position vector away from UIParent's
-- origin (~2.2x on the reporter's screen) and parks the button far outside the ring; the
-- denominator is UIParent again because that is the space the single
-- `SetPoint("CENTER", UIParent, ...)` below reads.
local function RingGeometry()
    local scaleRatio = Minimap:GetEffectiveScale() / UIParent:GetEffectiveScale();
    local x, y = Minimap:GetCenter();
    return x * scaleRatio, y * scaleRatio, (Minimap:GetWidth() / 2 + DEFAULT_LIFT) * scaleRatio;
end

-- The one polar helper: an angle on the ring in, the viewport point on it out.
local function PointAtAngle(angle)
    local x, y, radius = RingGeometry();
    return x + radius * math.cos(angle), y + radius * math.sin(angle);
end

-- The angle around the minimap of any viewport point; the two-argument arctangent of
-- Lua 5.1 that Blizzard uses too (Blizzard_SharedXMLBase/MathUtil.lua:106).
local function AngleAt(x, y)
    local cx, cy = RingGeometry();
    return math.atan2(y - cy, x - cx);
end

-- The one way the frame is ever positioned: an angle becomes a point on the ring, so the
-- button centre cannot end up anywhere but on the circle.
local function ApplyAngle(angle)
    local x, y = PointAtAngle(angle);
    button:ClearAllPoints();
    button:SetPoint("CENTER", UIParent, "BOTTOMLEFT", x, y);
end

local function ApplyDefaultPosition()
    ApplyAngle(DEFAULT_ANGLE);
end

-- On drag stop: measure the angle the pointer left the button at, save it, and re-anchor
-- the frame on the ring — the raw GetCenter() pair v0.1.1 stored is gone by design.
local function SavePosition()
    local x, y = button:GetCenter();
    if not x or not y then
        return;
    end
    -- GetCenter answers in the button's own space and AngleAt reads UIParent space, like
    -- SetPoint does, so the pair is converted exactly as v0.1.5 converted it — v0.1.6
    -- dropped the ratio here while it was also using the wrong one in RingGeometry.
    local scaleRatio = button:GetEffectiveScale() / UIParent:GetEffectiveScale();
    local angle = AngleAt(x * scaleRatio, y * scaleRatio);
    QuickBindsDB.minimapButton = { angle = angle };
    ApplyAngle(angle);
end

local function RestorePosition()
    local pos = QuickBindsDB and QuickBindsDB.minimapButton;
    -- `{ x = ..., y = ... }`: a v0.1.1 save with no angle. Load the ring angle that
    -- point implies instead of the free coordinates, so old saves keep their button.
    local angle = pos and (pos.angle or (pos.x and pos.y and AngleAt(pos.x, pos.y)));
    if angle then
        ApplyAngle(angle);
    else
        ApplyDefaultPosition();
    end
end

function QuickBinds.RecenterButton()
    if QuickBindsDB then
        QuickBindsDB.minimapButton = nil;
    end
    ApplyDefaultPosition();
    DEFAULT_CHAT_FRAME:AddMessage("Quick Binds: button re-centered above the minimap.");
end

local function CreateButton()
    -- Parented to `Minimap`, not to the cluster the ring art belongs to: `MinimapCluster`
    -- inherits `ResizeLayoutFrame` (Blizzard_Minimap/Mainline/Minimap.xml:3), so it
    -- resizes itself to fit every child — the v0.1.6 regression, where borrowing the
    -- cluster's stratum by parenting to it grew the minimap's edit-mode frame from 201 px
    -- to 326 px. `Minimap` is the plain 198x198 frame (Minimap.xml:179) the other addon
    -- buttons live on and its children never move those bounds; the ring itself is
    -- `MinimapCompassTexture` (`atlas="ui-hud-minimap-frame"`) on `MinimapBackdrop`
    -- (Minimap.xml:219-238), and the rank that clears it comes from `raiseSource` instead
    -- of from the parent. Clients with no `MinimapCluster` global read it off the
    -- minimap's own frame, exactly as v0.1.6's fallback did.
    raiseSource = MinimapCluster or Minimap;
    button = CreateFrame("Button", "QuickBindsMinimapButton", Minimap);
    RaiseAboveBorder();
    button:SetSize(SIZE, SIZE);
    button:SetClampedToScreen(true);
    button:EnableMouse(true);
    button:SetMovable(true);
    button:RegisterForDrag("LeftButton");

    -- The disc art is the shape: the TGA's alpha is a geometric circle, so nothing here
    -- needs a mask. (The TempPortraitAlphaMask this file used on a colour plate renders
    -- square on this client, which is why the button read as a blocky keycap.) The "QB"
    -- font string is the fallback for a client that cannot load the art.
    local icon = button:CreateTexture(nil, "ARTWORK");
    icon:SetAllPoints(true);

    local label = button:CreateFontString(nil, "OVERLAY", "GameFontNormal");
    label:SetPoint("CENTER");
    label:SetText("QB");

    if icon:SetTexture(ICON_PATH) == false then
        icon:Hide();
    else
        label:Hide();
    end

    button:SetHighlightTexture(MOUSE_HILIGHT, "ADD");

    button:RegisterForClicks("LeftButtonUp", "RightButtonUp");
    button:SetScript("OnClick", function(self, buttonName)
        if buttonName == "RightButton" then
            QuickBinds.EnterQuickKeybindMode();
        elseif buttonName == "LeftButton" then
            QuickBinds.OpenKeybindSettings();
        end
    end);

    button:SetScript("OnEnter", function(self)
        GameTooltip:SetOwner(self, "ANCHOR_RIGHT");
        GameTooltip:SetText("Quick Binds", 1, 1, 1);
        GameTooltip:AddLine("Right-click: Quick Keybind Mode");
        GameTooltip:AddLine("Left-click: Keybindings panel");
        GameTooltip:Show();
    end);
    button:SetScript("OnLeave", function()
        GameTooltip:Hide();
    end);

    button:SetScript("OnDragStart", function(self)
        self:StartMoving();
    end);
    button:SetScript("OnDragStop", function(self)
        self:StopMovingOrSizing();
        SavePosition();
    end);
end

local init = CreateFrame("Frame");
init:RegisterEvent("ADDON_LOADED");
-- The client restamps the cluster's child levels after ADDON_LOADED and rebuilds its
-- layout when the UI scale changes, so the raise (and the position that depends on the
-- resulting scales) is re-applied for both instead of being set once at creation.
init:RegisterEvent("PLAYER_ENTERING_WORLD");
init:RegisterEvent("UI_SCALE_CHANGED");
init:SetScript("OnEvent", function(self, event, addonName)
    if event == "ADDON_LOADED" then
        if addonName ~= "QuickBinds" then
            return;
        end
        self:UnregisterEvent("ADDON_LOADED");
        QuickBindsDB = QuickBindsDB or {};
        CreateButton();
        RestorePosition();
    elseif event == "PLAYER_ENTERING_WORLD" or event == "UI_SCALE_CHANGED" then
        -- The level and the anchor both depend on frames the client just rebuilt — the
        -- cluster's rank and the minimap's scale — so the pair is recomputed here.
        if button then
            RaiseAboveBorder();
            RestorePosition();
        end
    end
end);

SLASH_QUICKBINDSCENTER1 = "/qbcenter";
SlashCmdList["QUICKBINDSCENTER"] = function()
    QuickBinds.RecenterButton();
end;
